"""Debian package version comparison. See task.md."""

from __future__ import annotations

import re
import string
from functools import cmp_to_key
from itertools import zip_longest

_DIGITS = frozenset(string.digits)
_UPSTREAM_CHARS = frozenset(string.ascii_letters + string.digits + ".+~-:")
_REVISION_CHARS = frozenset(string.ascii_letters + string.digits + ".+~")
_NON_DIGIT_RUN = re.compile(r"[^0-9]*")
_DIGIT_RUN = re.compile(r"[0-9]*")


class VersionError(ValueError):
    """Raised for a string that is not a valid Debian version."""


def _invalid(version: str) -> VersionError:
    return VersionError(f"invalid Debian version: {version!r}")


def _parse(version: str) -> tuple[str, str, str]:
    epoch, colon, rest = version.partition(":")
    if colon:
        if not epoch or not _DIGITS.issuperset(epoch):
            raise _invalid(version)
    else:
        epoch, rest = "0", version

    upstream, dash, revision = rest.rpartition("-")
    if dash:
        if not revision or not _REVISION_CHARS.issuperset(revision):
            raise _invalid(version)
    else:
        upstream, revision = rest, "0"

    if not upstream or upstream[0] not in _DIGITS or not _UPSTREAM_CHARS.issuperset(upstream):
        raise _invalid(version)
    return epoch, upstream, revision


def _cmp(x, y) -> int:
    return (x > y) - (x < y)


def _cmp_numeric(a: str, b: str) -> int:
    a = a.lstrip("0")
    b = b.lstrip("0")
    return _cmp(len(a), len(b)) or _cmp(a, b)


def _char_weight(c: str | None) -> int:
    if c is None:
        return 0
    if c == "~":
        return -1
    if c in string.ascii_letters:
        return ord(c)
    return ord(c) + 256


def _split_run(pattern: re.Pattern[str], s: str) -> tuple[str, str]:
    end = pattern.match(s).end()
    return s[:end], s[end:]


def _verrevcmp(a: str, b: str) -> int:
    while a or b:
        non_digits_a, a = _split_run(_NON_DIGIT_RUN, a)
        non_digits_b, b = _split_run(_NON_DIGIT_RUN, b)
        for ca, cb in zip_longest(non_digits_a, non_digits_b):
            result = _cmp(_char_weight(ca), _char_weight(cb))
            if result:
                return result

        digits_a, a = _split_run(_DIGIT_RUN, a)
        digits_b, b = _split_run(_DIGIT_RUN, b)
        result = _cmp_numeric(digits_a, digits_b)
        if result:
            return result
    return 0


def compare(a: str, b: str) -> int:
    """Return -1, 0 or 1 as `a` sorts before, equal to, or after `b`."""
    epoch_a, upstream_a, revision_a = _parse(a)
    epoch_b, upstream_b, revision_b = _parse(b)
    return (
        _cmp_numeric(epoch_a, epoch_b)
        or _verrevcmp(upstream_a, upstream_b)
        or _verrevcmp(revision_a, revision_b)
    )


def sort_versions(versions: list[str]) -> list[str]:
    """Return `versions` in ascending order; equal versions keep their input order."""
    for version in versions:
        _parse(version)
    return sorted(versions, key=cmp_to_key(compare))
